async function compressImage(file: File): Promise<{ dataBase64: string; contentType: "image/jpeg" | "image/webp"; fileName: string }> {
  const bitmap = await createImageBitmap(file);
  const maxSize = 1800;
  const scale = Math.min(1, maxSize / Math.max(bitmap.width, bitmap.height));
  const canvas = document.createElement("canvas"); canvas.width = Math.round(bitmap.width * scale); canvas.height = Math.round(bitmap.height * scale);
  const context = canvas.getContext("2d"); if (!context) throw new Error("تعذر تجهيز الصورة");
  context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
  const blob = await new Promise<Blob>((resolve, reject) => canvas.toBlob((value) => value ? resolve(value) : reject(new Error("تعذر ضغط الصورة")), "image/webp", 0.82));
  const bytes = new Uint8Array(await blob.arrayBuffer()); let binary = ""; bytes.forEach((byte) => { binary += String.fromCharCode(byte); });
  return { dataBase64: btoa(binary), contentType: "image/webp", fileName: file.name.replace(/\.[^.]+$/, ".webp") };
}

