function PanelHeader({ title, meta, icon: Icon }: { title: string; meta: string; icon: typeof Boxes }) { return <div className="panel-header"><div className="flex items-center gap-2"><div className="panel-icon"><Icon size={16} /></div><h3>{title}</h3></div><button onClick={() => toast.info(meta)} className="panel-meta">{meta}<ArrowLeft size={12} /></button></div>; }

function OrdersPage({ orders, search, setSearch, onApprove }: { orders: Order[]; search: string; setSearch: (value: string) => void; onApprove: (id: string) => void }) {
  return <div className="page-stack"><div className="page-intro"><div><div className="eyebrow">التجارة والتوزيع</div><h2>الطلبات الواردة</h2><p>تابع طلبات التجار من لحظة الاستلام وحتى الخصم من المخزون.</p></div><button className="primary-button" onClick={() => toast.success("تم فتح نموذج طلب جديد")}>طلب جديد <Plus size={17} /></button></div><div className="toolbar"><div className="search-box"><Search size={17} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="ابحث برقم الطلب أو اسم التاجر" /></div><div className="filter-pills"><button className="filter-pill active">كل الطلبات <span>١٢</span></button><button className="filter-pill">معلقة <span>٣</span></button><button className="filter-pill">قيد التجهيز <span>٥</span></button><button className="filter-pill">مكتملة <span>٤</span></button></div></div><div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>رقم الطلب</th><th>التاجر</th><th>طريقة الطلب</th><th>الأصناف</th><th>القيمة</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{orders.map((order) => <tr key={order.id}><td><span className="font-bold text-[#344a45]">{order.id}</span><div className="mt-1 text-[10px] text-[#a4adaa]">{order.time}</div></td><td><div className="flex items-center gap-2"><div className="order-avatar small" style={{ background: order.color }}>{order.trader.slice(0, 1)}</div><div><div className="font-bold">{order.trader}</div><div className="mt-1 text-[10px] text-[#96a19d]">{order.area}</div></div></div></td><td><span className="channel-badge">{order.channel === "مندوب" ? <Truck size={12} /> : <Store size={12} />}{order.channel}</span></td><td className="text-[#6e7d78]">{order.items}</td><td className="font-bold">{order.total}</td><td><StatusBadge status={order.status} /></td><td>{order.status === "معلق" ? <button className="approve-button" onClick={() => onApprove(order.id)}><Check size={14} /> اعتماد</button> : <button className="more-button" onClick={() => toast.info(`تفاصيل ${order.id}`)}><MoreHorizontal size={17} /></button>}</td></tr>)}</tbody></table></div></div><OrderStatusManager /></div>;
}

function InventoryPage({ warehouse, setWarehouse }: { warehouse: string; setWarehouse: (value: string) => void }) {
  return <div className="page-stack"><div className="page-intro"><div><div className="eyebrow">المخزون والتوزيع</div><h2>المخازن والأرصدة</h2><p>كل حركة مخزون لها مصدر ووجهة وسجل واضح.</p></div><div className="flex gap-2"><button className="secondary-button" onClick={() => toast.success("تم فتح نموذج تحويل مخزون")}><ArrowRightLeft size={16} /> تحويل بين المخازن</button><button className="primary-button" onClick={() => toast.success("تم فتح نموذج إضافة رصيد افتتاحي")}><Plus size={17} /> إضافة مخزن</button></div></div><div className="warehouse-cards">{warehouses.map((item) => <div className={`warehouse-card ${item.tone}`} key={item.code}><div className="flex items-start justify-between"><div className="warehouse-symbol"><Warehouse size={17} /></div><span className="code-chip">{item.code}</span></div><div className="mt-5 text-[14px] font-bold text-[#2d4842]">{item.name}</div><div className="mt-1 text-[11px] text-[#7d8b86]">{item.type}</div><div className="mt-5 flex items-end justify-between"><div><div className="text-[11px] text-[#81908a]">قيمة المخزون</div><div className="mt-1 text-[20px] font-bold tracking-[-0.05em] text-[#2b4841]">{item.value} <small className="text-[10px] font-normal">ج.م</small></div></div><div className="text-left"><div className="text-[11px] text-[#81908a]">الامتلاء</div><div className="mt-1 text-[13px] font-bold text-[#547367]">{item.stock}</div></div></div><div className="mt-4 h-1.5 rounded-full bg-black/10"><div className="h-full rounded-full bg-[#47796e]" style={{ width: item.stock }} /></div></div>)}</div><div className="split-grid"><div className="panel"><PanelHeader title="مستويات الخامات" meta="عرض حركة المخزون" icon={Package} />{ingredients.map((ingredient) => <div className="ingredient-row" key={ingredient.name}><div className="ingredient-bullet" style={{ background: ingredient.color }} /><div className="min-w-0 flex-1"><div className="flex justify-between gap-2"><span className="text-[12px] font-bold text-[#374c47]">{ingredient.name}</span><span className="text-[11px] font-semibold text-[#778580]">{ingredient.qty}</span></div><div className="mt-2 h-2 rounded-full bg-[#edf0ed]"><div className="h-full rounded-full" style={{ width: `${ingredient.level}%`, background: ingredient.level < 30 ? "#cf6650" : ingredient.color }} /></div></div></div>)}</div><div className="panel"><PanelHeader title="كشف حركة المخزون" meta="آخر 24 ساعة" icon={ArrowRightLeft} /><div className="movement-row"><span className="movement-icon in"><ArrowDownLeft size={15} /></span><div className="flex-1"><b>استلام خامات إنتاج</b><span>المخزن الرئيسي • اليوم 11:42</span></div><strong className="text-[#4b8a71]">+ ٢٤٠ كجم</strong></div><div className="movement-row"><span className="movement-icon out"><ArrowUpRight size={15} /></span><div className="flex-1"><b>تحويل لتوزيع القاهرة</b><span>المخزن الرئيسي • اليوم 10:18</span></div><strong className="text-[#c3694d]">− ٨٥ وحدة</strong></div><div className="movement-row"><span className="movement-icon out"><Factory size={15} /></span><div className="flex-1"><b>صرف لدورة تصنيع</b><span>كريم كراميل • اليوم 09:22</span></div><strong className="text-[#c3694d]">− ٢ كجم</strong></div><button className="full-link-button" onClick={() => toast.info("سجل الحركة الكامل قيد الربط بقاعدة البيانات")}>فتح سجل الحركة <ArrowLeft size={14} /></button></div></div><InventoryManager /><WarehouseManager /><RealInventoryActivity /></div>;
}

function ProductionPage() {
  const [recipe, setRecipe] = useState("كريم كراميل 80 جم");
  return <div className="page-stack"><div className="page-intro"><div><div className="eyebrow">التصنيع والوصفات</div><h2>دورات الإنتاج</h2><p>أنشئ دورة تصنيع وسيتم خصم مكونات الوصفة من المخزن تلقائياً.</p></div><button className="primary-button" onClick={() => toast.success("تم إنشاء دورة تصنيع جديدة")}>دورة تصنيع <Plus size={17} /></button></div><div className="production-layout"><div className="panel recipe-panel"><PanelHeader title="إنشاء دورة تصنيع" meta="وصفة المنتج" icon={Factory} /><div className="field-label">المنتج النهائي</div><div className="select-field"><select value={recipe} onChange={(e) => setRecipe(e.target.value)}><option>كريم كراميل 80 جم</option><option>جيلي فراولة 70 جم</option><option>خلطة كريسبي حار 250 جم</option></select><ChevronDown size={15} /></div><div className="field-label mt-5">الكمية المطلوب تصنيعها</div><div className="quantity-row"><input defaultValue="20" /><span>كرتونة</span><div className="conversion-note">= 40 كجم خام</div></div><div className="recipe-preview"><div className="flex items-center justify-between"><div><div className="text-[12px] font-bold text-[#344b45]">الوصفة المعتمدة</div><div className="mt-1 text-[10px] text-[#8a9793]">آخر تعديل منذ 3 أيام بواسطة المدير العام</div></div><span className="approved-chip"><CheckCircle2 size={13} /> معتمدة</span></div><div className="recipe-lines"><div><span>سكر أبيض</span><b>١٠٠ جم</b></div><div><span>نكهة كريم كراميل</span><b>١٠ جم</b></div><div><span>ملح غذائي</span><b>٢٠ جم</b></div><div><span>عبوة + كرتونة</span><b>١ وحدة</b></div></div></div><button className="primary-button w-full justify-center" onClick={() => toast.success(`تم بدء تصنيع ${recipe}`)}>بدء دورة التصنيع <Factory size={16} /></button></div><div className="panel"><PanelHeader title="دورات التصنيع النشطة" meta="كل الدورات" icon={ClipboardList} /><div className="production-card active"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><div className="production-icon"><Factory size={18} /></div><div><div className="text-[13px] font-bold">كريم كراميل 80 جم</div><div className="mt-1 text-[10px] text-[#8d9995]">دورة #BATCH-0902 • بدأ 09:22 ص</div></div></div><span className="in-progress-chip"><span />قيد التصنيع</span></div><div className="mt-5 flex items-end justify-between"><div className="text-[11px] text-[#8b9793]">التقدم <b className="mr-1 text-[#385e55]">٦٥٪</b></div><div className="text-[11px] text-[#8b9793]">١٣ من ٢٠ كرتونة</div></div><div className="mt-2 h-2 rounded-full bg-[#e7ebe7]"><div className="h-full w-[65%] rounded-full bg-[#467b6d]" /></div><div className="mt-4 flex justify-between text-[10px] text-[#98a49f]"><span>صرف الخامات ✓</span><span>التعبئة جارية</span><span>الفحص النهائي</span></div></div><div className="production-card"><div className="flex items-center justify-between"><div className="flex items-center gap-3"><div className="production-icon peach"><Package size={18} /></div><div><div className="text-[13px] font-bold">جيلي فراولة 70 جم</div><div className="mt-1 text-[10px] text-[#8d9995]">دورة #BATCH-0901 • بدأ أمس</div></div></div><span className="done-chip"><Check size={13} /> مكتملة</span></div><div className="mt-4 text-[11px] text-[#788781]">تم إنتاج <b className="text-[#385e55]">١٢٠ كرتونة</b> وتحويلها إلى مخزن التوزيع.</div></div></div></div><RecipeDetailsManager /></div>;
}

function PartnersPage() {
  return <div className="page-stack"><div className="page-intro"><div><div className="eyebrow">شبكة التجار</div><h2>التجار والعملاء</h2><p>ملف موحد لكل تاجر، بعناوينه وطلباته والمندوب المسؤول عنه.</p></div><button className="primary-button" onClick={() => toast.success("تم فتح نموذج إضافة تاجر")}>إضافة تاجر <Plus size={17} /></button></div><div className="partner-overview"><div className="partner-overview-card"><UsersRound size={19} /><div><b>١,٢٨٤</b><span>إجمالي التجار</span></div></div><div className="partner-overview-card"><MapPinned size={19} /><div><b>١,١٠٨</b><span>عناوين نشطة</span></div></div><div className="partner-overview-card"><Truck size={19} /><div><b>١٢</b><span>مندوب مرتبط</span></div></div><div className="partner-overview-card"><ArrowUpRight size={19} /><div><b>٨٧٪</b><span>معدل إعادة الطلب</span></div></div></div><div className="panel table-panel"><div className="panel-header"><div className="flex items-center gap-2"><div className="panel-icon"><UsersRound size={16} /></div><h3>دليل التجار</h3></div><div className="search-box compact"><Search size={15} /><input placeholder="بحث بالاسم أو الهاتف" /></div></div><div className="table-scroll"><table><thead><tr><th>التاجر</th><th>الهاتف</th><th>المنطقة</th><th>المندوب المسؤول</th><th>آخر طلب</th><th>الحالة</th><th /></tr></thead><tbody>{[{ n: "سوبر ماركت الإيمان", p: "0101 234 5678", a: "مدينة نصر", r: "أحمد حسن", o: "منذ 18 دقيقة", s: "نشط" }, { n: "ماركت أولاد رجب", p: "0112 889 3210", a: "المعادي", r: "كريم محمود", o: "منذ 42 دقيقة", s: "نشط" }, { n: "البركة للتجارة", p: "0127 440 9182", a: "الهرم", r: "أحمد حسن", o: "أمس، 04:20 م", s: "نشط" }, { n: "محمود عطية", p: "0109 675 4432", a: "شبرا", r: "بدون مندوب", o: "منذ 3 أيام", s: "مراجعة" }].map((partner) => <tr key={partner.p}><td><div className="flex items-center gap-2"><div className="avatar avatar-small light-avatar">{partner.n.slice(0, 1)}</div><span className="font-bold">{partner.n}</span></div></td><td className="text-[#6d7c77]">{partner.p}</td><td>{partner.a}</td><td><span className="rep-chip">{partner.r}</span></td><td className="text-[#7c8b86]">{partner.o}</td><td><span className={partner.s === "نشط" ? "safe-badge" : "warning-badge"}>{partner.s}</span></td><td><button className="more-button" onClick={() => toast.info(`ملف ${partner.n}`)}><MoreHorizontal size={17} /></button></td></tr>)}</tbody></table></div></div><PeopleInvoicesManager /></div>;
}

function InvoicesPage() {
  const [selected, setSelected] = useState<string | null>(null);
  const [invoices, setInvoices] = useState([
    { id: "#INV-1092", trader: "سوبر ماركت الإيمان", rep: "أحمد حسن", total: "4,820 ج.م", discount: "0 ج.م", date: "16 سبتمبر 2026", status: "بانتظار الاعتماد", activity: ["تم إنشاء الفاتورة بواسطة أحمد حسن", "تم إرسالها للمدير العام"] },
    { id: "#INV-1091", trader: "ماركت أولاد رجب", rep: "كريم محمود", total: "2,340 ج.م", discount: "120 ج.م", date: "16 سبتمبر 2026", status: "معتمدة", activity: ["تم إنشاء الفاتورة", "تم تطبيق خصم 120 ج.م", "اعتمدتها سارة علي"] },
    { id: "#INV-1090", trader: "البركة للتجارة", rep: "أحمد حسن", total: "1,120 ج.م", discount: "0 ج.م", date: "15 سبتمبر 2026", status: "مرفوضة", activity: ["تم إنشاء الفاتورة", "تم رفضها: الخصم يحتاج مراجعة", "في انتظار تعديل المندوب"] },
    { id: "#INV-1089", trader: "محمود عطية", rep: "سارة علي", total: "8,760 ج.م", discount: "300 ج.م", date: "15 سبتمبر 2026", status: "ملغاة", activity: ["تم إنشاء الفاتورة", "تم إلغاؤها بناءً على طلب المندوب"] },
  ]);
  const [showActivity, setShowActivity] = useState(true);
  const activeInvoice = invoices.find((invoice) => invoice.id === selected);
  const updateStatus = (id: string, status: string, note: string) => {
    setInvoices((items) => items.map((invoice) => invoice.id === id ? { ...invoice, status, activity: [...invoice.activity, note] } : invoice));
    setSelected(id);
    toast.success(note);
  };
  const reject = (id: string) => {
    const reason = window.prompt("اكتب سبب رفض الفاتورة:", "يرجى مراجعة الخصم والكميات");
    if (!reason?.trim()) return;
    updateStatus(id, "مرفوضة", "تم رفضها: " + reason.trim());
  };
  return <div className="page-stack"><div className="page-intro"><div><div className="eyebrow">المبيعات والتحصيل</div><h2>الفواتير</h2><p>اعتماد، رفض بسبب، تعديل وإعادة إرسال مع سجل نشاط كامل.</p></div><button className="secondary-button" onClick={() => toast.info("التقرير سيُصدّر بعد ربط البيانات")}>تصدير التقرير <ArrowUpRight size={16} /></button></div><div className="invoice-summary"><div><span>إجمالي اليوم</span><b>١٧,٠٤٠ <small>ج.م</small></b></div><div><span>بانتظار الاعتماد</span><b className="orange-text">٤</b></div><div><span>تم رفضها</span><b className="orange-text">١</b></div><div><span>معتمدة اليوم</span><b className="green-text">١٨</b></div></div><div className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>رقم الفاتورة</th><th>التاجر</th><th>المندوب</th><th>الإجمالي</th><th>الخصم</th><th>الحالة</th><th>الإجراء</th></tr></thead><tbody>{invoices.map((invoice) => <tr key={invoice.id}><td className="font-bold text-[#344a45]">{invoice.id}<div className="mt-1 text-[10px] text-[#98a39f]">{invoice.date}</div></td><td>{invoice.trader}</td><td><span className="rep-chip">{invoice.rep}</span></td><td className="font-bold">{invoice.total}</td><td className="text-[#b16b4d]">{invoice.discount}</td><td><span className={invoice.status === "بانتظار الاعتماد" ? "warning-badge" : invoice.status === "مرفوضة" || invoice.status === "ملغاة" ? "critical-badge" : "safe-badge"}>{invoice.status}</span></td><td><div className="flex flex-wrap gap-2">{invoice.status === "بانتظار الاعتماد" && <><button className="approve-button" onClick={() => updateStatus(invoice.id, "معتمدة", "تم اعتماد الفاتورة وخصم الكمية من المخزن")}><Check size={14} /> اعتماد</button><button className="send-button" onClick={() => reject(invoice.id)}><XCircle size={14} /> رفض</button></>}{invoice.status === "مرفوضة" && <><button className="approve-button" onClick={() => updateStatus(invoice.id, "بانتظار الاعتماد", "تم تعديل الفاتورة وإعادة إرسالها للمراجعة")}><ArrowUpRight size={14} /> إعادة إرسال</button><button className="more-button" onClick={() => updateStatus(invoice.id, "ملغاة", "تم إلغاء الفاتورة بعد رفضها")}><X size={15} /></button></>}{invoice.status === "معتمدة" && <button className="send-button" onClick={() => toast.success("تم تجهيز رسالة واتساب بالبيانات واللوكيشن")}><Send size={14} /> واتساب</button>}<button className="more-button" onClick={() => { setSelected(invoice.id); setShowActivity(true); }}><MoreHorizontal size={17} /></button></div></td></tr>)}</tbody></table></div></div>{activeInvoice && showActivity && <div className="panel mt-4"><div className="panel-header"><div className="flex items-center gap-2"><div className="panel-icon"><Clock3 size={16} /></div><h3>سجل نشاط {activeInvoice.id}</h3></div><button className="more-button" onClick={() => setShowActivity(false)}><X size={15} /></button></div><div className="audit-row"><div className="avatar avatar-small green-avatar">{activeInvoice.rep.slice(0, 1)}</div><div><b>{activeInvoice.trader} • {activeInvoice.rep}</b><span>الخصم الحالي: {activeInvoice.discount} • الحالة: {activeInvoice.status}</span></div></div>{activeInvoice.activity.map((item, index) => <div className="audit-row" key={activeInvoice.id + "-" + index}><Clock3 size={15} /><div><b>{item}</b><span>{index === activeInvoice.activity.length - 1 ? "آخر نشاط الآن" : "سجل محفوظ في نشاط الفاتورة"}</span></div><span className="audit-tag">نشاط</span></div>)}</div>}</div>;
}

function TeamPage() {
  const [checked, setChecked] = useState<string[]>(["أحمد حسن", "كريم محمود"]);
  const toggle = (name: string) => setChecked((value) => value.includes(name) ? value.filter((item) => item !== name) : [...value, name]);
  return <div className="page-stack"><div className="page-intro"><div><div className="eyebrow">فريق المبيعات</div><h2>الحضور والانصراف</h2><p>تسجيل إلزامي بالوقت والموقع لكل مندوب ميداني.</p></div><button className="primary-button" onClick={() => toast.info("سجل الحضور اليومي سيُعرض هنا")}>سجل اليوم <CalendarDays size={16} /></button></div><div className="attendance-banner"><div className="attendance-copy"><div className="hero-kicker"><Fingerprint size={15} /> حضور ميداني موثق</div><h3>٤ من ٦ أعضاء سجلوا حضورهم اليوم</h3><p>آخر تحديث منذ 6 دقائق، جميع التسجيلات مرتبطة بإحداثيات الموقع.</p></div><div className="attendance-ring"><b>٦٧٪</b><span>حضور</span></div></div><div className="panel table-panel"><div className="panel-header"><div className="flex items-center gap-2"><div className="panel-icon"><UsersRound size={16} /></div><h3>حالة الفريق اليوم</h3></div><span className="text-[11px] text-[#8a9792]">آخر مزامنة: 09:18 ص</span></div><div className="table-scroll"><table><thead><tr><th>المندوب</th><th>الدور</th><th>الحضور</th><th>وقت التسجيل</th><th>الموقع</th><th>الطلبات اليوم</th><th>تحديد</th></tr></thead><tbody>{reps.map((rep) => <tr key={rep.name}><td><div className="flex items-center gap-2"><div className="avatar avatar-small" style={{ background: rep.color }}>{rep.initials}</div><span className="font-bold">{rep.name}</span></div></td><td className="text-[#7c8a85]">{rep.role}</td><td><span className={rep.today === "حاضر" ? "safe-badge" : rep.today === "متأخر" ? "warning-badge" : "critical-badge"}>{rep.today}</span></td><td className="font-semibold">{rep.time}</td><td><span className="location-chip"><MapPinned size={12} />{rep.today === "غائب" ? "—" : "الفرع الرئيسي"}</span></td><td className="font-bold text-[#375b53]">{rep.orders}</td><td><button className={`check-box ${checked.includes(rep.name) ? "checked" : ""}`} onClick={() => toggle(rep.name)}>{checked.includes(rep.name) && <Check size={14} />}</button></td></tr>)}</tbody></table></div></div></div>;
}

function SettingsPage() {
  const [push, setPush] = useState(true);
  const [lowStock, setLowStock] = useState(true);
  return <div className="page-stack"><div className="page-intro"><div><div className="eyebrow">التحكم في النظام</div><h2>الإعدادات والصلاحيات</h2><p>صمّم طريقة تشغيل النظام حسب أدوار فريقك.</p></div><button className="secondary-button" onClick={() => toast.success("تم حفظ الإعدادات")}>حفظ التغييرات <Check size={16} /></button></div><div className="settings-layout"><div className="panel permissions-panel"><PanelHeader title="الأدوار والصلاحيات" meta="إدارة المستخدمين" icon={UserCog} /><div className="role-line selected"><div className="role-avatar dark">م</div><div className="flex-1"><b>المدير العام</b><span>صلاحية كاملة • ١ مستخدم</span></div><ShieldCheck size={17} className="text-[#4d8376]" /></div><div className="role-line"><div className="role-avatar green">س</div><div className="flex-1"><b>مدير المبيعات</b><span>الطلبات، الفواتير، التجار • ١ مستخدم</span></div><ChevronDown size={15} className="text-[#9aa5a1]" /></div><div className="role-line"><div className="role-avatar orange">أ</div><div className="flex-1"><b>المندوب</b><span>طلبات العملاء، الفواتير، الحضور • ٦ مستخدمين</span></div><ChevronDown size={15} className="text-[#9aa5a1]" /></div><button className="full-link-button mt-3" onClick={() => toast.success("تم فتح نموذج إضافة مستخدم")}>إضافة مستخدم ودور جديد <Plus size={14} /></button></div><div className="panel settings-panel"><PanelHeader title="الإشعارات" meta="تُرسل فوراً" icon={Bell} /><ToggleRow title="إشعارات الطلبات الجديدة" caption="للمدير العام ومدير المبيعات" value={push} onChange={() => setPush(!push)} /><ToggleRow title="تنبيه انخفاض المخزون" caption="عند الوصول إلى الحد الأدنى" value={lowStock} onChange={() => setLowStock(!lowStock)} /><ToggleRow title="تحديثات الحضور الميداني" caption="تسجيل الحضور واللوكيشن" value={true} onChange={() => toast.info("هذا التنبيه إلزامي للمندوبين")} locked /></div></div><HeroSlidesSettings /><ProductImagesSettings /><div className="panel audit-panel"><PanelHeader title="سجل العمليات" meta="عرض السجل الكامل" icon={ClipboardList} /><div className="audit-row"><Clock3 size={15} /><div><b>اعتماد فاتورة #INV-1091</b><span>سارة علي • مدير المبيعات • منذ 35 دقيقة</span></div><span className="audit-tag">فاتورة</span></div><div className="audit-row"><ArrowRightLeft size={15} /><div><b>تحويل ٨٥ وحدة إلى توزيع القاهرة</b><span>محمد عادل • المدير العام • منذ ساعة</span></div><span className="audit-tag">مخزون</span></div><div className="audit-row"><UserCog size={15} /><div><b>تعديل وصفة كريم كراميل</b><span>محمد عادل • المدير العام • أمس، 03:14 م</span></div><span className="audit-tag">تصنيع</span></div></div></div>;
}

function ToggleRow({ title, caption, value, onChange, locked }: { title: string; caption: string; value: boolean; onChange: () => void; locked?: boolean }) { return <div className="toggle-row"><div><b>{title}</b><span>{caption}</span></div><button className={`toggle ${value ? "on" : ""}`} onClick={onChange} disabled={locked}><span /></button></div>; }


function InventoryManager() { const { user } = useAuth();
  const [warehouses, setWarehouses] = useState<{ id: string; name: string; warehouse_type: string }[]>([]); const [form, setForm] = useState({ sku: '', name: '', productType: 'finished', unit: 'كرتونة', price: '0', reorder: '0', warehouse: '', quantity: '0' }); const [file, setFile] = useState<File | null>(null); const uploadImage = trpc.media.uploadStoreImage.useMutation();
  useEffect(() => { supabase.from('warehouses').select('id, name, warehouse_type').eq('is_active', true).order('name').then(({ data }) => { if (data) { setWarehouses(data); if (data[0]) setForm((value) => ({ ...value, warehouse: data[0].id })); } }); }, []);
  const save = async () => { if (!form.sku || !form.name || !form.warehouse) return toast.error('أكمل كود المنتج والاسم والمخزن'); let imageUrl = ''; if (file) { const compressed = await compressImage(file); const uploaded = await uploadImage.mutateAsync(compressed); imageUrl = uploaded.url; } const { error } = await supabase.rpc('create_product_with_stock_manus', { p_sku: form.sku, p_name: form.name, p_product_type: form.productType, p_unit: form.unit, p_sale_price: Number(form.price), p_reorder_level: Number(form.reorder), p_image_url: imageUrl, p_warehouse_id: form.warehouse, p_opening_quantity: Number(form.quantity), p_manus_open_id: user?.openId || '' }); if (error) return toast.error(error.message || 'تعذر حفظ المنتج'); toast.success('تم إضافة المنتج ورصيد المخزن'); setForm({ ...form, sku: '', name: '', quantity: '' }); setFile(null); };
  return <div className="panel inventory-manager"><PanelHeader title="إضافة منتج ورصيد مخزن" meta="منتج جديد" icon={Package} /><div className="inventory-form-grid"><input placeholder="كود المنتج SKU" value={form.sku} onChange={(e) => setForm({ ...form, sku: e.target.value })} /><input placeholder="اسم المنتج أو المادة" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /><select value={form.productType} onChange={(e) => setForm({ ...form, productType: e.target.value })}><option value="finished">منتج جاهز للمتجر</option><option value="raw">مادة خام غذائية</option><option value="packaging">مادة باكدجنج</option><option value="semi_finished">مصنّع وسيط</option></select><input placeholder="الوحدة: كجم، كرتونة..." value={form.unit} onChange={(e) => setForm({ ...form, unit: e.target.value })} /><input type="number" placeholder="سعر البيع" value={form.price} onChange={(e) => setForm({ ...form, price: e.target.value })} /><input type="number" placeholder="حد إعادة الطلب" value={form.reorder} onChange={(e) => setForm({ ...form, reorder: e.target.value })} /><select value={form.warehouse} onChange={(e) => setForm({ ...form, warehouse: e.target.value })}><option value="">اختر المخزن</option>{warehouses.map((warehouse) => <option key={warehouse.id} value={warehouse.id}>{warehouse.name}</option>)}</select><input type="number" placeholder="الرصيد الافتتاحي" value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })} /><label className="upload-image-button"><Package size={15} /> {file ? file.name : 'صورة المنتج'}<input type="file" accept="image/png,image/jpeg,image/webp" onChange={(e) => setFile(e.target.files?.[0] || null)} /></label><button className="primary-button" onClick={save} disabled={uploadImage.isPending}><Plus size={15} /> حفظ المنتج والرصيد</button></div><p className="settings-help">منتجات الجاهز تظهر في المتجر، والخامات والباكدجنج تدخل في الوصفات والتصنيع. يتم تسجيل الرصيد الافتتاحي وحركة المخزن تلقائياً.</p></div>;
}
function OrderStatusManager() { const { user } = useAuth();
  const [orders, setOrders] = useState<{ order_number: string; status: string; notes: string | null; total: number; sales_rep_id: string | null }[]>([]); const [reps, setReps] = useState<{ id: string; full_name: string; phone: string | null }[]>([]); const [selected, setSelected] = useState(''); const [status, setStatus] = useState('confirmed'); const [note, setNote] = useState(''); const [location, setLocation] = useState(''); const [rep, setRep] = useState('');
  const load = () => { supabase.from('orders').select('order_number,status,notes,total,sales_rep_id').order('created_at', { ascending: false }).limit(25).then(({ data }) => { if (data) setOrders(data); }); supabase.from('profiles').select('id,full_name,phone').eq('role','sales_rep').eq('is_active',true).then(({ data }) => { if (data) setReps(data); }); };
  useEffect(load, []);
  const update = async () => { if (!selected) return toast.error('اختر طلباً'); const { error } = await supabase.rpc('update_public_order_status_manus', { p_order_number: selected, p_status: status, p_note: note, p_location: location, p_sales_rep_id: rep || null, p_manus_open_id: user?.openId || '' }); if (error) return toast.error(error.message || 'تعذر تحديث الطلب'); toast.success('تم تحديث حالة الطلب'); setNote(''); load(); };
  return <div className="panel order-status-manager"><PanelHeader title="تحديث الطلبات والشحن" meta="يظهر للتاجر فوراً" icon={Truck} /><div className="order-manager-grid"><select value={selected} onChange={(e) => setSelected(e.target.value)}><option value="">اختر رقم الطلب</option>{orders.map((order) => <option key={order.order_number} value={order.order_number}>{order.order_number} — {order.status}</option>)}</select><select value={status} onChange={(e) => setStatus(e.target.value)}><option value="confirmed">تم التأكيد</option><option value="preparing">قيد التجهيز</option><option value="shipped">خرج للشحن</option><option value="delivered">تم التسليم</option><option value="cancelled">ملغي</option></select><select value={rep} onChange={(e) => setRep(e.target.value)}><option value="">اختر المندوب</option>{reps.map((item) => <option key={item.id} value={item.id}>{item.full_name} — {item.phone}</option>)}</select><input value={location} onChange={(e) => setLocation(e.target.value)} placeholder="موقع الشحنة أو الفرع" /><textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="ملاحظة تظهر للعميل في التتبع" /><button className="primary-button" onClick={update}>حفظ التحديث وإرسال الإشعار <Check size={15} /></button></div><div className="order-manager-list">{orders.slice(0, 6).map((order) => <div key={order.order_number}><b>{order.order_number}</b><span>{order.status}</span><small>{order.notes || 'بدون ملاحظات'}</small></div>)}</div></div>;
}


function WarehouseManager() { const { user } = useAuth();
  const [warehouses, setWarehouses] = useState<{ id: string; name: string; code: string; warehouse_type: string; driver_profile_id: string | null; is_active: boolean }[]>([]); const [reps, setReps] = useState<{ id: string; full_name: string; phone: string | null }[]>([]); const [form, setForm] = useState({ name: '', code: '', type: 'main', rep: '' });
  const load = () => { supabase.from('warehouses').select('id,name,code,warehouse_type,driver_profile_id,is_active').eq('is_active', true).order('name').then(({ data }) => data && setWarehouses(data)); supabase.from('profiles').select('id,full_name,phone').eq('role','sales_rep').eq('is_active', true).order('full_name').then(({ data }) => data && setReps(data)); };
  useEffect(load, []);
  const save = async () => { if (!form.name || !form.code) return toast.error('اكتب اسم وكود المخزن'); const { error } = await supabase.rpc('create_warehouse_manus', { p_name: form.name, p_code: form.code, p_warehouse_type: form.type, p_driver_profile_id: form.rep || null, p_manus_open_id: user?.openId || '' }); if (error) return toast.error(error.message || 'تعذر إضافة المخزن'); toast.success('تمت إضافة المخزن'); setForm({ name: '', code: '', type: 'main', rep: '' }); load(); };
  return <div className="panel warehouse-manager"><PanelHeader title="إدارة المخازن" meta="مخزن جديد" icon={Warehouse} /><div className="warehouse-form-grid"><input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="اسم المخزن: الرئيسي أو توزيع القاهرة" /><input value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="الكود: MAIN-01" /><select value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}><option value="main">مخزن رئيسي</option><option value="distribution">مخزن توزيع</option><option value="packaging">مخزن باكدجنج</option><option value="vehicle">عربية توزيع</option></select><select value={form.rep} onChange={(e) => setForm({ ...form, rep: e.target.value })}><option value="">مندوب مسؤول اختياري</option>{reps.map((rep) => <option key={rep.id} value={rep.id}>{rep.full_name} — {rep.phone}</option>)}</select><button className="primary-button" onClick={save}><Plus size={15} /> إضافة المخزن</button></div><div className="warehouse-live-list">{warehouses.map((warehouse) => <div key={warehouse.id}><Warehouse size={16} /><div><b>{warehouse.name}</b><span>{warehouse.code} • {warehouse.warehouse_type}</span></div><em>{warehouse.driver_profile_id ? reps.find((rep) => rep.id === warehouse.driver_profile_id)?.full_name || 'مندوب مرتبط' : 'بدون مندوب'}</em></div>)}</div><p className="settings-help">أضف المخازن هنا أولاً، ثم ستظهر تلقائياً في نموذج المنتجات والأرصدة الافتتاحية.</p></div>;
}
function PeopleInvoicesManager() { const { user } = useAuth();
  const [traders, setTraders] = useState<{ id: string; business_name: string; contact_name: string | null; phone: string | null; assigned_rep_id: string | null }[]>([]); const [reps, setReps] = useState<{ id: string; full_name: string; phone: string | null }[]>([]); const [invoices, setInvoices] = useState<{ id: string; invoice_number: string; trader_id: string; total: number; status: string; created_at: string }[]>([]); const [filter, setFilter] = useState('all');
  const load = () => { supabase.from('traders').select('id,business_name,contact_name,phone,assigned_rep_id').eq('is_active', true).order('business_name').then(({ data }) => data && setTraders(data)); supabase.from('profiles').select('id,full_name,phone').eq('role','sales_rep').eq('is_active', true).order('full_name').then(({ data }) => data && setReps(data)); supabase.from('invoices').select('id,invoice_number,trader_id,total,status,created_at').order('created_at', { ascending: false }).limit(100).then(({ data }) => data && setInvoices(data)); };
  useEffect(load, []);
  const assign = async (traderId: string, repId: string) => { const { error } = await supabase.rpc('assign_trader_rep_manus', { p_trader_id: traderId, p_rep_id: repId || null, p_manus_open_id: user?.openId || '' }); if (error) return toast.error(error.message || 'تعذر ربط المندوب'); setTraders((items) => items.map((item) => item.id === traderId ? { ...item, assigned_rep_id: repId || null } : item)); toast.success('تم ربط التاجر بالمندوب'); };
  const repInvoices = (repId: string) => invoices.filter((invoice) => traders.find((trader) => trader.id === invoice.trader_id)?.assigned_rep_id === repId);
  return <div className="people-real-panel"><ProfileCreatePanel onSaved={load} /><div className="people-filter"><button className={filter === 'all' ? 'active' : ''} onClick={() => setFilter('all')}>التجار والفواتير</button><button className={filter === 'reps' ? 'active' : ''} onClick={() => setFilter('reps')}>المندوبون وفواتيرهم</button></div>{filter !== 'reps' && <div className="real-people-grid"><div className="panel"><PanelHeader title="بروفايلات التجار" meta={String(traders.length)} icon={UsersRound} />{traders.map((trader) => <div className="real-person-row" key={trader.id}><div><b>{trader.business_name}</b><span>{trader.contact_name || 'بدون مسؤول'} • {trader.phone || 'بدون هاتف'}</span><small>فواتير: {invoices.filter((invoice) => invoice.trader_id === trader.id).length}</small></div><select value={trader.assigned_rep_id || ''} onChange={(e) => assign(trader.id, e.target.value)}><option value="">بدون مندوب</option>{reps.map((rep) => <option key={rep.id} value={rep.id}>{rep.full_name}</option>)}</select></div>)}</div><div className="panel"><PanelHeader title="فواتير التجار" meta={String(invoices.length)} icon={ReceiptText} />{invoices.slice(0, 10).map((invoice) => <div className="real-invoice-row" key={invoice.id}><b>{invoice.invoice_number}</b><span>{traders.find((trader) => trader.id === invoice.trader_id)?.business_name || 'تاجر'}</span><strong>{Number(invoice.total || 0).toFixed(2)} ج.م</strong><em>{invoice.status}</em></div>)}</div></div>}{filter === 'reps' && <div className="real-people-grid"><div className="panel"><PanelHeader title="بروفايلات المندوبين" meta={String(reps.length)} icon={Truck} />{reps.map((rep) => <div className="real-person-row" key={rep.id}><div><b>{rep.full_name}</b><span>{rep.phone || 'بدون هاتف'}</span><small>فواتير التجار التابعين: {repInvoices(rep.id).length}</small></div><a href={rep.phone ? 'tel:' + rep.phone : undefined}><PhoneCall size={14} /></a></div>)}</div><div className="panel"><PanelHeader title="فواتير حسب المندوب" meta="بيانات فعلية" icon={ReceiptText} />{reps.flatMap((rep) => repInvoices(rep.id).slice(0, 10).map((invoice) => <div className="real-invoice-row" key={rep.id + invoice.id}><b>{invoice.invoice_number}</b><span>{rep.full_name}</span><strong>{Number(invoice.total || 0).toFixed(2)} ج.م</strong><em>{invoice.status}</em></div>))}</div></div>}</div>;
}


function RealInventoryActivity() { const [rows, setRows] = useState<any[]>([]); useEffect(() => { Promise.all([supabase.from('stock_movements').select('id,warehouse_id,product_id,movement_type,quantity,notes,created_at').order('created_at',{ascending:false}).limit(30), supabase.from('products').select('id,name').limit(200), supabase.from('warehouses').select('id,name').limit(50)]).then(([movements, productsData, warehousesData]) => { const productsMap = new Map((productsData.data || []).map((x) => [x.id, x.name])); const warehousesMap = new Map((warehousesData.data || []).map((x) => [x.id, x.name])); setRows((movements.data || []).map((x) => ({ ...x, product: productsMap.get(x.product_id) || 'منتج', warehouse: warehousesMap.get(x.warehouse_id) || 'مخزن' }))); }); }, []); return <div className="panel real-activity-panel"><PanelHeader title="كشف حركة المخزون" meta="آخر 30 حركة" icon={ArrowRightLeft} />{rows.length ? rows.map((row) => <div className="real-movement-row" key={row.id}><span className={Number(row.quantity) >= 0 ? 'movement-icon in' : 'movement-icon out'}>{Number(row.quantity) >= 0 ? <ArrowDownLeft size={14} /> : <ArrowUpRight size={14} />}</span><div><b>{row.product}</b><span>{row.warehouse} • {row.notes || row.movement_type}</span></div><strong className={Number(row.quantity) >= 0 ? 'in-text' : 'out-text'}>{Number(row.quantity) > 0 ? '+' : ''}{row.quantity}</strong><small>{new Date(row.created_at).toLocaleString('ar-EG')}</small></div>) : <div className="empty-real-state">لا توجد حركات مسجلة بعد</div>}</div>; }
function RealProductionManager() { const { user } = useAuth(); const [recipes, setRecipes] = useState<any[]>([]); const [batches, setBatches] = useState<any[]>([]); const [products, setProducts] = useState<any[]>([]); const [form, setForm] = useState({ product: '', name: '', output: '1' }); const load = () => { Promise.all([supabase.from('recipes').select('id,product_id,name,output_quantity,version,is_approved,created_at').order('created_at',{ascending:false}), supabase.from('production_batches').select('id,batch_number,recipe_id,planned_output,actual_output,status,started_at,completed_at').order('created_at',{ascending:false}).limit(20), supabase.from('products').select('id,name').order('name').limit(200)]).then(([r,b,p]) => { setRecipes(r.data || []); setBatches(b.data || []); setProducts(p.data || []); }); }; useEffect(load, []); const saveRecipe = async () => { if (!form.product || !form.name) return toast.error('اختر المنتج واكتب اسم الوصفة'); const { error } = await supabase.rpc('create_recipe_manus', { p_product_id: form.product, p_name: form.name, p_output_quantity: Number(form.output), p_manus_open_id: user?.openId || '' }); if (error) return toast.error(error.message || 'تعذر حفظ الوصفة'); toast.success('تم إنشاء الوصفة'); setForm({ product: '', name: '', output: '1' }); load(); }; return <div className="panel real-production-panel"><PanelHeader title="التصنيع والوصفات الحقيقية" meta={recipes.length + ' وصفة • ' + batches.length + ' دورة'} icon={Factory} /><div className="recipe-create-grid"><select value={form.product} onChange={(e) => setForm({ ...form, product: e.target.value })}><option value="">المنتج النهائي</option>{products.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select><input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="اسم الوصفة" /><input type="number" value={form.output} onChange={(e) => setForm({ ...form, output: e.target.value })} placeholder="كمية الناتج" /><button className="primary-button" onClick={saveRecipe}><Plus size={15} /> إنشاء وصفة</button></div><div className="real-production-grid"><div><h4>الوصفات</h4>{recipes.slice(0,8).map((r) => <div className="real-production-row" key={r.id}><b>{r.name}</b><span>{products.find((p) => p.id === r.product_id)?.name || 'منتج'} • ناتج {r.output_quantity}</span><em>{r.is_approved ? 'معتمدة' : 'مسودة'}</em></div>)}</div><div><h4>دورات التصنيع</h4>{batches.slice(0,8).map((b) => <div className="real-production-row" key={b.id}><b>{b.batch_number}</b><span>مخطط {b.planned_output} • فعلي {b.actual_output || 0}</span><em>{b.status}</em></div>)}</div></div></div>; }
function FinancialReportsPage() { const [invoices, setInvoices] = useState<any[]>([]); const [traders, setTraders] = useState<any[]>([]); const [reps, setReps] = useState<any[]>([]); useEffect(() => { Promise.all([supabase.from('invoices').select('id,invoice_number,trader_id,total,discount,status,created_at').order('created_at',{ascending:false}).limit(300), supabase.from('traders').select('id,business_name,assigned_rep_id').limit(300), supabase.from('profiles').select('id,full_name,phone').eq('role','sales_rep').limit(100)]).then(([i,t,r]) => { setInvoices(i.data || []); setTraders(t.data || []); setReps(r.data || []); }); }, []); const approved = invoices.filter((i) => ['approved','paid','sent','معتمدة'].includes(i.status)); const total = approved.reduce((sum, i) => sum + Number(i.total || 0), 0); const grouped = traders.map((trader) => ({ ...trader, invoices: invoices.filter((i) => i.trader_id === trader.id), total: invoices.filter((i) => i.trader_id === trader.id).reduce((sum, i) => sum + Number(i.total || 0), 0) })).filter((x) => x.invoices.length); return <div className="page-stack"><div className="page-intro"><div><div className="eyebrow">تقارير فعلية</div><h2>التقارير المالية</h2><p>إجماليات الفواتير والمبيعات حسب التاجر والمندوب من Supabase.</p></div></div><div className="report-stats"><div><b>{invoices.length}</b><span>إجمالي الفواتير</span></div><div><b>{total.toFixed(2)} ج.م</b><span>المبيعات المعتمدة</span></div><div><b>{grouped.length}</b><span>تجار لديهم فواتير</span></div></div><div className="real-people-grid"><div className="panel"><PanelHeader title="مبيعات كل تاجر" meta="بيانات حقيقية" icon={Store} />{grouped.map((item) => <div className="report-row" key={item.id}><div><b>{item.business_name}</b><span>{item.invoices.length} فاتورة</span></div><strong>{item.total.toFixed(2)} ج.م</strong></div>)}</div><div className="panel"><PanelHeader title="مبيعات حسب المندوب" meta="التجار التابعون" icon={Truck} />{reps.map((rep) => { const traderIds = traders.filter((t) => t.assigned_rep_id === rep.id).map((t) => t.id); const items = invoices.filter((i) => traderIds.includes(i.trader_id)); return <div className="report-row" key={rep.id}><div><b>{rep.full_name}</b><span>{items.length} فاتورة • {rep.phone || 'بدون هاتف'}</span></div><strong>{items.reduce((sum, i) => sum + Number(i.total || 0), 0).toFixed(2)} ج.م</strong></div>; })}</div></div><div className="panel table-panel"><PanelHeader title="آخر الفواتير" meta="عرض التفاصيل" icon={ReceiptText} /><div className="table-scroll"><table><thead><tr><th>الفاتورة</th><th>التاجر</th><th>المندوب</th><th>الإجمالي</th><th>الخصم</th><th>الحالة</th><th>التاريخ</th></tr></thead><tbody>{invoices.slice(0,30).map((invoice) => { const trader = traders.find((t) => t.id === invoice.trader_id); const rep = reps.find((r) => r.id === trader?.assigned_rep_id); return <tr key={invoice.id}><td>{invoice.invoice_number}</td><td>{trader?.business_name || '—'}</td><td>{rep?.full_name || '—'}</td><td>{Number(invoice.total || 0).toFixed(2)} ج.م</td><td>{Number(invoice.discount || 0).toFixed(2)} ج.م</td><td>{invoice.status}</td><td>{new Date(invoice.created_at).toLocaleDateString('ar-EG')}</td></tr>; })}</tbody></table></div></div></div>; }


function ProfileCreatePanel({ onSaved }: { onSaved: () => void }) { const { user } = useAuth(); const [form, setForm] = useState({ name: '', phone: '', manusOpenId: '' }); const save = async () => { if (!form.name || !form.phone) return toast.error('اكتب اسم المندوب ورقم هاتفه'); const { error } = await supabase.rpc('create_profile_manus', { p_full_name: form.name, p_phone: form.phone, p_role: 'sales_rep', p_manus_open_id: user?.openId || '', p_new_manus_open_id: form.manusOpenId || null }); if (error) return toast.error(error.message || 'تعذر إنشاء ملف المندوب'); toast.success('تم إنشاء ملف المندوب'); setForm({ name: '', phone: '', manusOpenId: '' }); onSaved(); }; return <div className="panel profile-create-panel"><PanelHeader title="إضافة حساب مندوب" meta="profiles" icon={UserCog} /><div><input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="اسم المندوب" /><input value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} placeholder="رقم الهاتف" /><input value={form.manusOpenId} onChange={(e) => setForm({ ...form, manusOpenId: e.target.value })} placeholder="Manus openId اختياري" /><button className="primary-button" onClick={save}><Plus size={15} /> حفظ في profiles</button></div><p className="settings-help">استخدم openId عند رغبتك في ربط حساب Manus محدد بالمندوب.</p></div>; }


function RecipeDetailsManager() { const { user } = useAuth(); const [products, setProducts] = useState<any[]>([]); const [recipes, setRecipes] = useState<any[]>([]); const [form, setForm] = useState({ product: '', name: '', output: '1', version: '1' }); const [items, setItems] = useState<{ product: string; quantity: string; type: 'raw' | 'packaging' }[]>([{ product: '', quantity: '', type: 'raw' }]); const load = () => { Promise.all([supabase.from('products').select('id,name,unit,product_type').eq('is_active', true).in('product_type', ['finished','raw','packaging','semi_finished']).order('name'), supabase.from('recipes').select('id,name,output_quantity,version,product_id,is_approved').order('created_at', { ascending: false }).limit(20)]).then(([p,r]) => { setProducts(p.data || []); setRecipes(r.data || []); }); }; useEffect(load, []); const ingredients = products.filter((p) => p.product_type === 'raw' || p.product_type === 'packaging' || p.product_type === 'semi_finished'); const addLine = () => setItems((lines) => [...lines, { product: '', quantity: '', type: 'raw' }]); const updateLine = (index: number, patch: Partial<{ product: string; quantity: string; type: 'raw' | 'packaging' }>) => setItems((lines) => lines.map((line, lineIndex) => lineIndex === index ? { ...line, ...patch } : line)); const save = async () => { const validItems = items.filter((item) => item.product && Number(item.quantity) > 0); if (!form.product || !form.name || !validItems.length) return toast.error('اختر المنتج النهائي وأضف مكوناً واحداً على الأقل'); const { error } = await supabase.rpc('create_recipe_with_items_manus', { p_product_id: form.product, p_name: form.name, p_output_quantity: Number(form.output), p_version: Number(form.version), p_items: validItems.map((item) => ({ product_id: item.product, quantity: Number(item.quantity), item_type: item.type })), p_manus_open_id: user?.openId || '' }); if (error) return toast.error(error.message || 'تعذر حفظ الوصفة'); toast.success('تم حفظ الوصفة ومكوناتها'); setForm({ product: '', name: '', output: '1', version: '1' }); setItems([{ product: '', quantity: '', type: 'raw' }]); load(); }; return <div className="panel recipe-details-panel"><PanelHeader title="إدخال وصفة دقيقة" meta="خامات وتغليف" icon={Factory} /><div className="recipe-details-head"><select value={form.product} onChange={(e) => setForm({ ...form, product: e.target.value })}><option value="">المنتج النهائي</option>{products.filter((p) => p.product_type === 'finished').map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}</select><input value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="اسم الوصفة: كريم كراميل 80 جم" /><input type="number" value={form.output} onChange={(e) => setForm({ ...form, output: e.target.value })} placeholder="الناتج" /><input type="number" value={form.version} onChange={(e) => setForm({ ...form, version: e.target.value })} placeholder="الإصدار" /></div><div className="recipe-items-head"><b>المكونات</b><span>اختَر المواد من المخازن وحدد الكمية لكل ناتج</span></div><div className="recipe-items-table"><div className="recipe-item-header"><span>المادة الخام أو التغليف</span><span>الكمية</span><span>النوع</span><span /></div>{items.map((item, index) => <div className="recipe-item-line" key={index}><select value={item.product} onChange={(e) => updateLine(index, { product: e.target.value })}><option value="">اختر مادة</option>{ingredients.map((product) => <option key={product.id} value={product.id}>{product.name} • {product.unit || 'وحدة'} • {product.product_type === 'packaging' ? 'تغليف' : 'خام'}</option>)}</select><input type="number" min="0.001" step="0.001" value={item.quantity} onChange={(e) => updateLine(index, { quantity: e.target.value })} placeholder="0.000" /><select value={item.type} onChange={(e) => updateLine(index, { type: e.target.value as 'raw' | 'packaging' })}><option value="raw">خام غذائي</option><option value="packaging">مواد تغليف</option></select><button className="more-button" onClick={() => setItems((lines) => lines.filter((_, lineIndex) => lineIndex !== index))}><X size={14} /></button></div>)}</div><div className="recipe-details-actions"><button className="secondary-button" onClick={addLine}><Plus size={15} /> إضافة مكوّن</button><button className="primary-button" onClick={save}><Check size={15} /> حفظ الوصفة كاملة</button></div><div className="saved-recipes-list">{recipes.slice(0, 8).map((recipe) => <div key={recipe.id}><b>{recipe.name}</b><span>إصدار {recipe.version} • ناتج {recipe.output_quantity}</span><em>{recipe.is_approved ? 'معتمدة' : 'في انتظار الاعتماد'}</em></div>)}</div></div>; }

function Storefront({ cart, onBack, onAdd }: { cart: string[]; onBack: () => void; onAdd: (name: string) => void }) {
  type StoreView = 'home' | 'product' | 'offers' | 'cart' | 'checkout' | 'success' | 'tracking';
  type StoreProduct = typeof products[number] & { id?: string; image_url?: string | null };
  const [catalog, setCatalog] = useState<StoreProduct[]>(products);
  const [view, setView] = useState<StoreView>('home');
  const [selectedProduct, setSelectedProduct] = useState<StoreProduct | null>(null);
  const [selectedCategory, setSelectedCategory] = useState('الكل');
  const [slides, setSlides] = useState([{ title: 'طعم الفاكهة الأصلي', subtitle: 'مع جيلي بيور', cta_label: 'تسوق الآن', image_url: 'https://files.manuscdn.com/user_upload_by_module/session_file/310519663954061026/qxrfvCMOCddzDFwM.jpg' }]);
  const [offers, setOffers] = useState<{id:string; title:string; description:string|null; discount_text:string|null; image_url:string|null}[]>([]);
  const [activeSlide, setActiveSlide] = useState(0);
  const [form, setForm] = useState({ businessName: '', contactName: '', phone: '', address: '', notes: '' });
  const [location, setLocation] = useState<{ lat: number; lng: number } | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [trackingForm, setTrackingForm] = useState({ orderNumber: '', phone: '' });
  const [tracking, setTracking] = useState<any>(null);
  const [phoneOrders, setPhoneOrders] = useState<any[]>([]);
  const [trackingLoading, setTrackingLoading] = useState(false);
  const notifyNewOrder = trpc.store.notifyOrderCreated.useMutation();
  useEffect(() => {
    let active = true;
    supabase.from('products').select('id, name, sku, sale_price, product_type, image_url').eq('is_active', true).eq('product_type', 'finished').order('name').then(({ data }) => {
      if (active && data?.length) setCatalog(data.map((product, index) => ({ id: product.id, image_url: product.image_url, name: product.name, sku: product.sku, price: Number(product.sale_price || 0).toFixed(2), stock: 0, color: ['#c7352f', '#eb9d19', '#5d953b', '#e24f38', '#d3bd39'][index % 5] })));
    });
    supabase.from('store_hero_slides').select('title, subtitle, cta_label, image_url').eq('is_active', true).order('sort_order').then(({ data }) => { if (active && data?.length) setSlides(data); });
    supabase.from('store_offers').select('id, title, description, discount_text, image_url').eq('is_active', true).order('created_at', { ascending: false }).then(({ data }) => { if (active && data) setOffers(data); });
    return () => { active = false; };
  }, []);
  useEffect(() => { const timer = window.setInterval(() => setActiveSlide((value) => (value + 1) % slides.length), 5200); return () => window.clearInterval(timer); }, [slides.length]);
  const cartProducts = cart.map((name) => catalog.find((product) => product.name === name)).filter(Boolean) as StoreProduct[];
  const categoryFor = (product: StoreProduct) => product.name.includes('جيلي') ? 'جيلي وسناكس' : product.name.includes('كريم') || product.name.includes('معلب') ? 'معلبات' : product.name.includes('خلطة') || product.name.includes('بهار') ? 'بهارات وخلطات' : product.name.includes('أرز') || product.name.includes('بقول') ? 'بقوليات ومكسرات' : 'منتجات طبيعية';
  const visibleCatalog = selectedCategory === 'الكل' ? catalog : catalog.filter((product) => categoryFor(product) === selectedCategory);
  const total = cartProducts.reduce((sum, product) => sum + Number(product.price), 0);
  const goProduct = (product: StoreProduct) => { setSelectedProduct(product); setView('product'); };
  const addAndStay = (product: StoreProduct) => { onAdd(product.name); toast.success('تمت إضافة المنتج إلى السلة'); };
  const submitOrder = async () => {
    if (!form.businessName || !form.phone || !form.address) return toast.error('من فضلك أكمل اسم المتجر ورقم الهاتف والعنوان');
    const items = cartProducts.filter((product) => product.id).map((product) => ({ product_id: product.id, quantity: 1 }));
    if (!items.length) return toast.error('المنتجات التجريبية تحتاج إدخال المنتجات الحقيقية في Supabase أولاً');
    setSubmitting(true);
    const { data: createdOrder, error } = await supabase.rpc('submit_public_order', { p_business_name: form.businessName, p_contact_name: form.contactName, p_phone: form.phone, p_address: form.address, p_latitude: location?.lat ?? null, p_longitude: location?.lng ?? null, p_notes: form.notes, p_items: items });
    setSubmitting(false);
    if (error) return toast.error(error.message || 'تعذر إرسال الطلب');
    try { await notifyNewOrder.mutateAsync({ businessName: form.businessName, phone: form.phone, total: `${total.toFixed(2)} ج.م` }); } catch { /* notification is best effort */ }
    if (createdOrder?.order_number) setTrackingForm({ orderNumber: createdOrder.order_number, phone: form.phone }); setView('success'); toast.success('تم إرسال طلبك بنجاح');
  };
  const loadTracking = async () => { if (!trackingForm.phone.trim()) return toast.error('اكتب رقم هاتف التاجر المسجل'); setTrackingLoading(true); const { data, error } = await supabase.rpc('get_public_orders_by_phone', { p_phone: trackingForm.phone.trim() }); setTrackingLoading(false); if (error || !Array.isArray(data) || !data.length) return toast.error('لا توجد طلبات مرتبطة بهذا الرقم'); setPhoneOrders(data); setTracking(null); setView('tracking'); };
  const loadOneTracking = (order: any) => setTracking(order);
  const trackingRepresentative = tracking?.order?.sales_rep || (tracking?.order?.representative_name ? { name: tracking.order.representative_name, phone: tracking.order.representative_phone } : null);
  const nav = (next: StoreView) => setView(next);
  const Header = () => <header className="store-topbar"><button className="store-brand-lockup" onClick={() => nav('home')}><img className="store-real-logo" src="https://files.manuscdn.com/user_upload_by_module/session_file/310519663954061026/sHJXxOuFhntaMcJc.png" alt="بيور اختياراتك الطبيعية" /></button><nav className="store-links"><button className={view === 'home' ? 'active' : ''} onClick={() => nav('home')}>الرئيسية</button><button className={view === 'cart' ? 'active' : ''} onClick={() => nav('cart')}>السلة</button><button className={view === 'tracking' ? 'active' : ''} onClick={() => nav('tracking')}>طلباتي</button></nav><div className="store-search"><Search size={17} /><input aria-label="بحث" placeholder="إبحث عن منتجك المفضل..." onChange={(event) => { const found = catalog.find((product) => product.name.includes(event.target.value)); if (event.target.value && found) goProduct(found); }} /></div><div className="store-actions"><button className="store-cart" onClick={() => nav('cart')}><ShoppingBag size={20} /><span>{cart.length}</span></button><button className="store-mobile-menu"><Menu size={20} /></button><button className="back-admin" onClick={onBack}>لوحة الإدارة</button></div></header>;
  const Hero = () => <section className="store-hero-reference"><div className="hero-overlay-copy"><div className="store-logo-watermark">بيور</div><h1>{slides[activeSlide]?.title}</h1><p>{slides[activeSlide]?.subtitle}</p><span>بدون أي إضافات صناعية</span><button onClick={() => nav('home')}>{slides[activeSlide]?.cta_label || 'تسوق الآن'} <ArrowLeft size={16} /></button></div><img src={slides[activeSlide]?.image_url} alt={slides[activeSlide]?.title} /><div className="hero-controls"><button onClick={() => setActiveSlide((activeSlide - 1 + slides.length) % slides.length)}><ArrowRightLeft size={15} /></button><div>{slides.map((_, index) => <button key={index} className={index === activeSlide ? 'active' : ''} onClick={() => setActiveSlide(index)} />)}</div><button onClick={() => setActiveSlide((activeSlide + 1) % slides.length)}><ArrowLeft size={15} /></button></div></section>;
  const Categories = () => <section className="category-strip"><button className={selectedCategory === 'الكل' ? 'active' : ''} onClick={() => setSelectedCategory('الكل')}><span>⌂</span><b>كل المنتجات</b></button>{['منتجات طبيعية', 'معلبات', 'بقوليات ومكسرات', 'بهارات وخلطات', 'جيلي وسناكس'].map((label, index) => <button className={selectedCategory === label ? 'active' : ''} key={label} onClick={() => setSelectedCategory(label)}><span>{['◌','◒','▱','◍','♧'][index]}</span><b>{label}</b></button>)}</section>;
  const ProductCard = ({ product }: { product: StoreProduct }) => <article className="product-card-reference"><button className="product-photo" onClick={() => goProduct(product)}>{product.image_url ? <img className="product-real-image" src={product.image_url} alt={product.name} /> : <div className="product-pack"><span>بيور</span><b>{product.name.split(' ').slice(0, 2).join(' ')}</b><i>طبيعي 100%</i></div>}</button><button className="product-title-button" onClick={() => goProduct(product)}><h3>{product.name}</h3><p>{categoryFor(product)}</p></button><strong>{product.price} <small>ج.م</small></strong><button className="reference-add" onClick={() => addAndStay(product)}>أضف إلى السلة <ShoppingBag size={14} /></button></article>;
  const HomePage = () => <><Hero /><Categories /><section id="store-products" className="store-product-section"><div className="store-section-heading"><div><span>{selectedCategory === 'الكل' ? 'اختيارات بيور' : selectedCategory}</span><h2>منتجاتنا <em>المميزة</em></h2></div><span className="catalog-count">{visibleCatalog.length} منتج</span></div><div className="product-grid">{visibleCatalog.map((product) => <ProductCard key={product.sku} product={product} />)}</div>{!visibleCatalog.length && <div className="empty-store-state"><h3>لا توجد منتجات في هذا التصنيف بعد</h3><button className="primary-button" onClick={() => setSelectedCategory('الكل')}>عرض كل المنتجات</button></div>}</section></>;
  const ProductPage = () => selectedProduct ? <section className="store-detail-page"><button className="store-back-link" onClick={() => nav('home')}><ArrowRightLeft size={15} /> العودة للمنتجات</button><div className="product-detail-card"><div className="product-detail-art"><div className="product-pack large"><span>بيور</span><b>{selectedProduct.name}</b><i>طبيعي 100%</i></div></div><div className="product-detail-copy"><span className="eyebrow">منتج PURE الأصلي</span><h1>{selectedProduct.name}</h1><p>منتج عالي الجودة من مصنع بيور للمواد الغذائية، مناسب لطلبات التجار بالجملة.</p><strong>{selectedProduct.price} <small>ج.م</small></strong><div className="detail-meta"><span><CheckCircle2 size={15} /> متوفر للطلب</span><span><Truck size={15} /> شحن سريع</span></div><button className="reference-add large-button" onClick={() => addAndStay(selectedProduct)}>أضف إلى السلة <ShoppingBag size={17} /></button></div></div></section> : <HomePage />;
  const OffersPage = () => <section className="store-inner-page"><div className="store-section-heading"><div><span>لفترة محدودة</span><h2>العروض <em>الحالية</em></h2></div><button onClick={() => nav('home')}>العودة للمتجر <ArrowLeft size={15} /></button></div><div className="offers-grid">{(offers.length ? offers : slides.map((slide, index) => ({ id: String(index), title: slide.title, description: slide.subtitle, discount_text: 'عرض بيور', image_url: slide.image_url }))).map((offer) => <article className="offer-card" key={offer.id}><img src={offer.image_url || slides[0].image_url} alt={offer.title} /><div><span>{offer.discount_text || 'عرض خاص'}</span><h3>{offer.title}</h3><p>{offer.description}</p><button onClick={() => nav('home')}>تسوق الآن <ArrowLeft size={14} /></button></div></article>)}</div></section>;
  const CartPage = () => <section className="store-inner-page"><div className="store-section-heading"><div><span>مراجعة الطلب</span><h2>سلة <em>التسوق</em></h2></div><button onClick={() => nav('home')}>متابعة التسوق <ArrowLeft size={15} /></button></div>{cartProducts.length ? <div className="cart-layout"><div className="cart-items">{cartProducts.map((product, index) => <div className="cart-line" key={product.sku + index}><div className="mini-product-pack">بيور</div><div><b>{product.name}</b><span>كرتونة واحدة • {product.price} ج.م</span></div><strong>{product.price} ج.م</strong></div>)}</div><div className="cart-summary"><h3>ملخص الطلب</h3><div><span>عدد المنتجات</span><b>{cartProducts.length}</b></div><div><span>الإجمالي</span><strong>{total.toFixed(2)} ج.م</strong></div><button className="primary-button full-width" onClick={() => nav('checkout')}>إتمام الطلب <ArrowLeft size={16} /></button></div></div> : <div className="empty-store-state"><ShoppingBag size={34} /><h3>السلة فارغة</h3><p>أضف منتجاتك المفضلة وابدأ طلب الجملة.</p><button className="primary-button" onClick={() => nav('home')}>تصفح المنتجات</button></div>}</section>;
  const CheckoutPage = () => <section className="store-inner-page"><div className="store-section-heading"><div><span>خطوة أخيرة</span><h2>بيانات <em>التوصيل</em></h2></div><button onClick={() => nav('cart')}>السلة <ArrowLeft size={15} /></button></div><div className="checkout-layout"><form className="checkout-form" onSubmit={(event) => { event.preventDefault(); submitOrder(); }}><label>اسم المتجر*<input value={form.businessName} onChange={(event) => setForm({ ...form, businessName: event.target.value })} placeholder="مثال: سوبر ماركت الإيمان" required /></label><label>اسم المسؤول<input value={form.contactName} onChange={(event) => setForm({ ...form, contactName: event.target.value })} placeholder="الاسم بالكامل" /></label><label>رقم الهاتف*<input type="tel" value={form.phone} onChange={(event) => setForm({ ...form, phone: event.target.value })} placeholder="01xxxxxxxxx" required /></label><label>عنوان التوصيل*<textarea value={form.address} onChange={(event) => setForm({ ...form, address: event.target.value })} placeholder="المحافظة، المنطقة، الشارع والعلامة المميزة" required /></label><div className="location-picker-field"><div><b>حدد موقع المحل على الخريطة</b><span>{location ? `تم تحديد الموقع: ${location.lat.toFixed(5)}, ${location.lng.toFixed(5)}` : "اضغط على الخريطة أو استخدم موقعك الحالي"}</span></div><button type="button" onClick={() => navigator.geolocation?.getCurrentPosition((position) => setLocation({ lat: position.coords.latitude, lng: position.coords.longitude }), () => toast.error("تعذر قراءة موقعك الحالي"))}><MapPinned size={15} /> موقعي الحالي</button><MapView className="checkout-map" initialCenter={location || { lat: 30.0444, lng: 31.2357 }} initialZoom={11} onMapReady={(map) => { map.addListener("click", (event: google.maps.MapMouseEvent) => { const point = event.latLng?.toJSON(); if (point) setLocation({ lat: point.lat, lng: point.lng }); }); }} /></div><label>ملاحظات الطلب<textarea value={form.notes} onChange={(event) => setForm({ ...form, notes: event.target.value })} placeholder="أي ملاحظات للمندوب" /></label><button className="primary-button full-width" disabled={submitting}>{submitting ? 'جاري إرسال الطلب...' : 'تأكيد وإرسال الطلب'}</button></form><div className="checkout-summary"><h3>ملخص الطلب</h3>{cartProducts.map((product, index) => <div key={product.sku + index}><span>{product.name}</span><b>{product.price} ج.م</b></div>)}<hr /><strong>الإجمالي {total.toFixed(2)} ج.م</strong><p><ShieldCheck size={15} /> بياناتك محفوظة وتصل مباشرة لفريق PURE</p></div></div></section>;
  const TrackingPage = () => <section className="store-inner-page tracking-page"><div className="store-section-heading"><div><span>طلبات التاجر</span><h2>تتبع <em>طلباتي</em></h2></div><button onClick={() => nav('home')}>العودة للرئيسية <ArrowLeft size={15} /></button></div>{!tracking && !phoneOrders.length ? <div className="tracking-search-card"><Truck size={32} /><h3>كل طلباتك في مكان واحد</h3><p>اكتب رقم الهاتف المسجل باسم التاجر لعرض الطلبات وحالات الشحن.</p><div className="tracking-phone-only"><input value={trackingForm.phone} onChange={(event) => setTrackingForm({ ...trackingForm, phone: event.target.value })} placeholder="رقم هاتف التاجر المسجل" /><button className="primary-button" onClick={loadTracking} disabled={trackingLoading}>{trackingLoading ? 'جاري البحث...' : 'عرض طلباتي'}</button></div></div> : <div className="tracking-result"><div className="tracking-order-head"><div><span>طلبات التاجر</span><b>{phoneOrders.length} طلب</b></div><div><span>الهاتف المسجل</span><strong>{trackingForm.phone}</strong></div></div><div className="merchant-orders-list">{phoneOrders.map((item: any) => <button className={`merchant-order-card ${tracking?.order?.order_number === item?.order?.order_number ? 'selected' : ''}`} key={item.order.order_number} onClick={() => loadOneTracking(item)}><div><b>{item.order.order_number}</b><span>{item.order.created_at ? new Date(item.order.created_at).toLocaleDateString('ar-EG') : 'طلب مسجل'}</span></div><strong>{item.order.status || item.events?.at(-1)?.title || 'قيد المتابعة'}</strong><em>{Number(item.order.total || 0).toFixed(2)} ج.م</em></button>)}</div>{tracking ? <><div className="tracking-rep-card">{trackingRepresentative ? <><div className="rep-card-icon"><Truck size={17} /></div><div><b>مندوب التوصيل</b><span>{trackingRepresentative.name}</span></div><a href={`tel:${trackingRepresentative.phone}`}><PhoneCall size={15} /> {trackingRepresentative.phone}</a></> : <><div className="rep-card-icon"><Clock3 size={17} /></div><div><b>جاري تعيين المندوب</b><span>سيظهر اسمه ورقم هاتفه عند خروجه للشحن</span></div></>}</div>{tracking.order.customer_note && <div className="customer-tracking-note">{tracking.order.customer_note}</div>}<div className="tracking-timeline">{tracking.events.map((event: any, index: number) => <div className={index === tracking.events.length - 1 ? 'tracking-event current' : 'tracking-event'} key={event.created_at + index}><div className="tracking-dot"><CheckCircle2 size={14} /></div><div><b>{event.title || event.status}</b><span>{event.description || event.note || ''}</span><small>{new Date(event.created_at).toLocaleString('ar-EG')}</small></div></div>)}</div></> : <p className="tracking-select-hint">اختار طلبًا من القائمة لعرض تفاصيل حالته والمندوب.</p>}<button className="secondary-button" onClick={() => { setTracking(null); setPhoneOrders([]); }}>بحث برقم آخر</button></div>}</section>;
  const SuccessPage = () => <div className="empty-store-state success-store-state"><CheckCircle2 size={55} /><h2>تم استلام طلبك بنجاح</h2><p>سيتواصل معك فريق PURE لتأكيد التفاصيل وموعد التوصيل.</p><b className="success-order-number">رقم الطلب: {trackingForm.orderNumber}</b><button className="primary-button" onClick={() => { setTracking(null); nav('tracking'); }}>تتبع حالة الطلب</button><button className="secondary-button" onClick={() => nav('home')}>العودة للمتجر</button></div>;
  return <div className="store-shell" dir="rtl"><Header /><main className="store-content">{view === 'home' && <HomePage />}{view === 'product' && <ProductPage />}{view === 'cart' && <CartPage />}{view === 'checkout' && <CheckoutPage />}{view === 'success' && <SuccessPage />}{view === 'tracking' && <TrackingPage />}</main><footer className="store-footer-reference"><div className="footer-brand"><img className="store-real-logo footer-real-logo" src="https://files.manuscdn.com/user_upload_by_module/session_file/310519663954061026/sHJXxOuFhntaMcJc.png" alt="بيور" /><span>اختياراتك الطبيعية</span><small>© 2025 PURE - جميع الحقوق محفوظة</small></div><div><b>تصفح سريع</b><button onClick={() => nav('home')}>الرئيسية</button><button onClick={() => nav('cart')}>السلة</button><button onClick={() => nav('tracking')}>طلباتي</button></div><div><b>التصنيفات</b><span>جيلي وسناكس</span><span>بهارات وخلطات</span><span>معلبات</span></div></footer></div>;
}

function HeroSlidesSettings() {
  const [slides, setSlides] = useState([{ title: "طعم الفاكهة الأصلي", image_url: "https://files.manuscdn.com/user_upload_by_module/session_file/310519663954061026/qxrfvCMOCddzDFwM.jpg", is_active: true }]);
  const [title, setTitle] = useState(""); const [imageUrl, setImageUrl] = useState(""); const [file, setFile] = useState<File | null>(null);
  const uploadImage = trpc.media.uploadStoreImage.useMutation();
  const addSlide = async () => {
    let finalUrl = imageUrl.trim();
    if (file) { const compressed = await compressImage(file); const uploaded = await uploadImage.mutateAsync(compressed); finalUrl = uploaded.url; }
    if (!title.trim() || !finalUrl) return toast.error("اكتب عنوان العرض واختر صورة أو ضع رابطها");
    const row = { title: title.trim(), image_url: finalUrl, is_active: true }; const { error } = await supabase.from("store_hero_slides").insert(row);
    if (error) return toast.error("تعذر حفظ الشريحة — تأكد من صلاحية المدير");
    setSlides((items) => [...items, row]); setTitle(""); setImageUrl(""); setFile(null); toast.success("تم رفع وإضافة شريحة Hero");
  };
  return <div className="panel hero-slides-panel"><PanelHeader title="صور الهيرو والعروض" meta="إدارة المتجر" icon={Store} /><p className="settings-help">ارفع صورة العرض مباشرة من جهازك أو استخدم رابطاً عاماً. الصور تضاف فوراً إلى Carousel المتجر.</p><div className="hero-slide-list">{slides.map((slide, index) => <div className="hero-slide-row" key={slide.image_url + index}><img src={slide.image_url} alt="" /><div><b>{slide.title}</b><span>{slide.is_active ? "نشطة في المتجر" : "متوقفة"}</span></div><button className="more-button" onClick={() => setSlides((items) => items.filter((_, itemIndex) => itemIndex !== index))}><X size={14} /></button></div>)}</div><div className="hero-slide-form"><input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="عنوان العرض" /><label className="upload-image-button"><Package size={15} /> {file ? file.name : "اختيار صورة"}<input type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => setFile(event.target.files?.[0] || null)} /></label><input value={imageUrl} onChange={(event) => setImageUrl(event.target.value)} placeholder="أو رابط صورة عامة" /><button className="primary-button" onClick={addSlide} disabled={uploadImage.isPending}><Plus size={15} /> {uploadImage.isPending ? "جاري الرفع..." : "إضافة صورة"}</button></div></div>;
}

function ProductImagesSettings() {
  const [items, setItems] = useState<{ id: string; name: string; image_url: string | null }[]>([]);
  const [selected, setSelected] = useState(""); const [file, setFile] = useState<File | null>(null); const uploadImage = trpc.media.uploadStoreImage.useMutation();
  useEffect(() => { supabase.from("products").select("id, name, image_url").eq("product_type", "finished").order("name").then(({ data }) => { if (data) setItems(data); }); }, []);
  const upload = async () => { if (!selected || !file) return toast.error("اختر المنتج والصورة أولاً"); const compressed = await compressImage(file); const result = await uploadImage.mutateAsync(compressed); const { error } = await supabase.from("products").update({ image_url: result.url }).eq("id", selected); if (error) return toast.error("تعذر حفظ صورة المنتج"); setItems((rows) => rows.map((row) => row.id === selected ? { ...row, image_url: result.url } : row)); setFile(null); toast.success("تم تحديث صورة المنتج"); };
  return <div className="panel hero-slides-panel"><PanelHeader title="صور المنتجات" meta="كتالوج المتجر" icon={Package} /><p className="settings-help">اربط صورة واضحة بكل منتج لتظهر في صفحة المتجر وصفحة المنتج.</p><div className="product-image-form"><select value={selected} onChange={(event) => setSelected(event.target.value)}><option value="">اختر المنتج</option>{items.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select><label className="upload-image-button"><Package size={15} /> {file ? file.name : "اختيار صورة المنتج"}<input type="file" accept="image/png,image/jpeg,image/webp" onChange={(event) => setFile(event.target.files?.[0] || null)} /></label><button className="primary-button" onClick={upload} disabled={uploadImage.isPending}><Plus size={15} /> {uploadImage.isPending ? "جاري الرفع..." : "رفع وحفظ"}</button></div><div className="product-image-thumbs">{items.slice(0, 8).map((item) => <div key={item.id}><div>{item.image_url ? <img src={item.image_url} alt="" /> : <Package size={18} />}</div><span>{item.name}</span></div>)}</div></div>;
}
